// 只展示本人购买的原服务与自己的已履约半日，最多16条；取消不抹已挣恢复点或补未供疗效。
#include "growth_recovery_views.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
V identity(const CommonStore& c){StableId world;const char* hex="0123456789abcdef";for(auto n:c.state().identity.world_id){world+=hex[n>>4];world+=hex[n&15];}const auto& i=c.state().identity;return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{i.execution_epoch}},{"revision",V{i.revision}},{"tick",V{i.tick}}});}
}
Outcome<BoundaryValue> growth_recovery_view(const CommonStore& c,const GrowthState& growth,const GrowthRecoveryCatalog& catalog,const GrowthRecoveryState& state,const GrowthRecoveryHistoryAccess& access,const StableId& actor,Integer page){using namespace boundary;if(actor!=c.state().metadata.player_actor_id)return {false,{},common_failure("GrowthRecoveryObserverMismatch").error};if(page<0||page>62500)return {false,{},common_failure("InvalidGrowthRecoveryPage").error};auto read=read_growth_recovery_progress_in_candidate(c,growth,catalog,state,access,actor);if(!read.ok)return {false,{},read.error};const auto* person=c.actor(actor);if(!person)return {false,{},common_failure("UnknownRecoveryActor",actor).error};V active;V::Array rows;Integer total=0;
for(auto it=c.state().facts.order().rbegin();it!=c.state().facts.order().rend();++it){const auto* credit=state.credits.find(*it);const auto* closed=state.closures.find(*it);const auto* service=credit?state.services.find(credit->action_id):closed?state.services.find(closed->action_id):nullptr;if(!service||service->actor_id!=actor)continue;if(total>=page*16&&total<(page+1)*16){rows.emplace_back(obj({{"source_fact_id",V{*it}},{"action_id",V{credit?credit->action_id:closed->action_id}},{"tick",V{credit?credit->tick:closed->tick}},{"kind",V{credit?"credit":"closed"}},{"method",V{service->method==GrowthRecoveryMethod::safe_lodging?"safe_lodging":"qualified_clinic"}},{"provided_points",V{credit?credit->used_points:0}},{"reason",V{closed?closed->reason:StableId{}}},{"provider_actor_id",V{service->provider_actor_id}},{"place_id",V{service->place_id}}}));}++total;}
if(const auto* service=state.services.find(person->action_id)){const auto* action=c.action(person->action_id);if(action)active=obj({{"action_id",V{action->id}},{"remaining_ticks",V{action->remaining_ticks}},{"duration",V{service->duration}},{"points_per_half_day",V{growth_recovery_service_points(service->method)}},{"provider_actor_id",V{service->provider_actor_id}},{"place_id",V{service->place_id}}});}
return {true,obj({{"actor_id",V{actor}},{"source_identity",identity(c)},{"injury",V{read.value.injury}},{"points_in_grade",V{read.value.points}},{"required_points",V{read.value.injury*4-read.value.points}},{"hp_limit",V{growth_injury_hp_limit(read.value.injury)}},{"active",std::move(active)},{"page",V{page}},{"total",V{total}},{"rows",V{std::move(rows)}},{"explanation",V{"安全住宿每个实际服务半日1点，合格医馆2点；4点减轻一级伤势。中止保留已经提供的点数，未提供时间不补计；再次加重伤势将重新计算本级进度。"}}}),{}};}
}
